          @click.prevent.stop="setOperationMode(OperationMode.SINGLE)"
          @touchstart.prevent.stop
          @touchend.prevent.stop="setOperationMode(OperationMode.SINGLE)"
          @mousedown.prevent.stop
          @mouseup.prevent.stop
        >
          <span>单手</span>
