      @mousedown.prevent="onTouchAreaStart"
    ></div>

    <!-- 移动摇杆 - 仅移动端显示 -->
    <div
      v-if="!isPCDevice"
      ref="moveJoystickRef"
      class="joystick move-joystick"
      :class="{ active: isDragging }"
      :style="{
        left: `${joystickPosition.x}px`,
        bottom: `${joystickPosition.y}px`,
        opacity: isDragging ? 1 : 0.6,
      }"
    >
      <div class="joystick-base">
        <!-- 外圈容器 - 带缺口的圆 -->
