                stroke-width="3" />
          <!-- 下方向连接线 -->
          <line x1="80" y1="155" x2="80" y2="168" stroke="rgba(255, 255, 255, 0.6)"
                stroke-width="2" />

          <!-- 左方向弧线 -->
          <path d="M 15 110 A 60 60 0 0 1 15 50" fill="none" stroke="rgba(200, 200, 200, 0.7)"
                stroke-width="3" />
          <!-- 左方向连接线 -->
          <line x1="5" y1="80" x2="-8" y2="80" stroke="rgba(255, 255, 255, 0.6)" stroke-width="2" />

          <!-- 中心小圆圈 -->
          <circle cx="80" cy="80" r="5.5" fill="none" stroke="rgba(200, 200, 200, 0.8)"
                  stroke-width="2" />

          <!-- 上方三角形 (指向上) -->
          <polygon points="80,30.4 62.65,49.6 97.35,49.6" fill="rgba(174, 174, 174, 0.8)" />

          <!-- 下方三角形 (指向下) -->
          <polygon points="80,129.6 62.65,110.4 97.35,110.4" fill="rgba(174, 174, 174, 0.8)" />

          <!-- 边缘绿色弧线 -->
          <path
            v-if="edgeArc.show"
            :d="edgeArc.path"
            fill="none"
            :stroke="`rgba(0, 255, 0, ${edgeArc.opacity})`"
            stroke-width="4"
            stroke-linecap="round"
          />
        </svg>

        <!-- 方向标签 -->
        <div class="direction-label top">W</div>
        <div class="direction-label right">R</div>
        <div class="direction-label bottom">S</div>
        <div class="direction-label left">L</div>

        <!-- 中心手柄 -->
        <div
          class="joystick-handle"
          :style="{
            transform: `translate(${moveHandle.x}px, ${moveHandle.y}px)`,
          }"
        ></div>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { onMounted, onUnmounted, reactive, ref } from 'vue';

interface JoystickData {
  x: number;
  y: number;
  angle: number;
  distance: number;
  edgeRatio?: number; // 边缘比例，范围[-1, 1]，-1表示最左边，1表示最右边，0表示中心
}

interface Props {
  isOrbitControlActive?: boolean;
  isOrbitControlManuallyActivated?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  isOrbitControlActive: false,
  isOrbitControlManuallyActivated: false,
});

// 通过 userAgent 判断是否为移动设备
const isMobileDevice = () => {
  const ua = navigator.userAgent.toLowerCase();
  return /android|webos|iphone|ipad|ipod|blackberry|iemobile|opera mini|mobile/i.test(ua);
};

// 判断是否为PC端
const isPCDevice = ref(!isMobileDevice());

const emit = defineEmits<{
  joystickMove: [data: JoystickData];
  runToggle: [isRunning: boolean];
  touchDelta: [delta: { x: number; y: number }];
  cameraRotationSpeed: [speed: number];
  operationModeChange: [mode: 'auto' | 'single' | 'dual'];
}>();

// 操作模式枚举
enum OperationMode {
  AUTO = 'auto',
  SINGLE = 'single',
  DUAL = 'dual',
}

// 当前操作模式
const currentOperationMode = ref<OperationMode>(OperationMode.DUAL);

// 获取设备DPI
const getDeviceDPI = (): number => {
  // 创建一个1英寸的div来测量DPI
  const div = document.createElement('div');
  div.style.width = '1in';
  div.style.visibility = 'hidden';
  div.style.position = 'absolute';
  document.body.appendChild(div);
  const dpi = div.offsetWidth;
  document.body.removeChild(div);
  return dpi || 96; // 默认96 DPI
};

// 像素转换为英寸
const pixelsToInches = (pixels: number, dpi: number): number => {
  return pixels / dpi;
};

// 英寸转换为像素
const inchesToPixels = (inches: number, dpi: number): number => {
  return inches * dpi;
};

const deviceDPI = getDeviceDPI();
console.log('设备DPI:', deviceDPI);

// 监听窗口大小变化（用于 DevTools 设备模拟切换）
const handleResize = () => {
  // 重新检测设备类型
  isPCDevice.value = !isMobileDevice();

  // 更新默认位置（如果摇杆不在拖动状态）
  if (!isDragging) {
    // 左下角位置保持不变，只需要更新边距
    joystickPosition.x = CONTROL_EDGE_MARGIN;
    joystickPosition.y = CONTROL_EDGE_MARGIN;
    defaultPosition.x = CONTROL_EDGE_MARGIN;
    defaultPosition.y = CONTROL_EDGE_MARGIN;
  }
};

// 控件边缘距离（像素）- 统一的边距
const CONTROL_EDGE_MARGIN = 30;

const moveJoystickRef = ref<HTMLDivElement>();
const moveHandle = reactive({ x: 0, y: 0 });

// 摇杆基座半径
const joystickRadius = window.innerWidth <= 768 ? 70 : 80;
// 竖屏：摇杆在左下角，距离左边和底部一致的边距
// 摇杆中心距离边缘 = CONTROL_EDGE_MARGIN + joystickRadius
const joystickPosition = reactive({
  x: CONTROL_EDGE_MARGIN,
  y: CONTROL_EDGE_MARGIN
});
const edgeArc = reactive({
  show: false,
  path: '',
  angle: 0,
  opacity: 0.8, // 弧线透明度
});

let isDragging = false;
let joystickCenter = { x: 0, y: 0 };
// 根据设备类型设置不同的最大移动距离
const maxDistance = window.innerWidth <= 768 ? 35 : 45; // 移动端35px，桌面端45px
let lastTouchPosition = { x: 0, y: 0 }; // 记录上一次触摸位置
let touchStart = { x: 0, y: 0 }; // 记录触摸起始位置
// 竖屏：摇杆默认在左下角
const defaultPosition = { x: CONTROL_EDGE_MARGIN, y: CONTROL_EDGE_MARGIN };
let lastTJoystickY = 0;
let activeTouchId: number | null = null; // 追踪当前激活的触摸点ID
let lastCameraSpeedUpdateTime = 0; // 记录上次调用updateCameraSpeed的时间戳
let referenceWidthInches = pixelsToInches(window.innerWidth * 0.25, deviceDPI); // 参考宽度（英寸），默认为屏幕宽度的1/4
let referencePoint = window.innerWidth * 0.25; // 参考点位置（像素），默认为屏幕宽度的1/4

// 弧线渐隐动画相关
let fadeOutAnimationId: number | null = null; // RAF动画ID
let fadeOutStartTime: number | null = null; // 渐隐开始时间
const FADE_OUT_DURATION = 50; // 渐隐持续时间（毫秒）
const sensitivityThreshold = isMobileDevice() ? 2 : 1; // 灵敏度阈值
// 检测是否为 Safari 浏览器
const isSafari = () => {
  return /^((?!chrome|android).)*safari/i.test(navigator.userAgent);
};

onMounted(() => {
  document.addEventListener('mousemove', onGlobalMouseMove);
  document.addEventListener('mouseup', onGlobalMouseUp);
  document.addEventListener('touchmove', onGlobalTouchMove, { passive: false });
  document.addEventListener('touchend', onGlobalTouchEnd);
  document.addEventListener('touchcancel', onGlobalTouchEnd); // Safari 需要监听 touchcancel
  window.addEventListener('resize', handleResize); // 监听窗口大小变化
});

onUnmounted(() => {
  document.removeEventListener('mousemove', onGlobalMouseMove);
  document.removeEventListener('mouseup', onGlobalMouseUp);
  document.removeEventListener('touchmove', onGlobalTouchMove);
  document.removeEventListener('touchend', onGlobalTouchEnd);
  document.removeEventListener('touchcancel', onGlobalTouchEnd);
  window.removeEventListener('resize', handleResize); // 移除窗口大小监听
});

function getEventPosition(event: MouseEvent | TouchEvent) {
  // 使用更安全的方式检测 TouchEvent，避免 Safari 中的 TouchEvent 未定义问题
  if ('touches' in event && event.touches && event.touches.length > 0) {
    // 如果有激活的触摸点ID，查找对应的触摸点
    if (activeTouchId !== null) {
      for (let i = 0; i < event.touches.length; i++) {
        if (event.touches[i].identifier === activeTouchId) {
          return {
            x: event.touches[i].clientX,
            y: event.touches[i].clientY,
          };
        }
      }
    }
    // 如果没有找到或没有激活ID，使用第一个触摸点
    return {
      x: event.touches[0]?.clientX || 0,
      y: event.touches[0]?.clientY || 0,
    };
  }
  return {
    x: (event as any).clientX,
    y: (event as any).clientY,
  };
}

function onTouchAreaStart(event: MouseEvent | TouchEvent) {
  // Safari 需要阻止默认行为
  event.preventDefault();

  // 如果是触摸事件，记录触摸点ID
  if ('touches' in event && event.touches && event.touches.length > 0) {
    // 查找在下部30%区域的触摸点（竖屏下摇杆区域）
    for (let i = 0; i < event.touches.length; i++) {
      const touch = event.touches[i];
      // 竖屏：下部30%为摇杆区域（即 y > 70% 屏幕高度）
      const isInJoystickArea = touch.clientY > window.innerHeight * 0.7;

      if (isInJoystickArea && activeTouchId === null) {
        // 找到第一个在摇杆区域的触摸点
        activeTouchId = touch.identifier;
        startJoystick({ x: touch.clientX, y: touch.clientY });
        return;
      }
    }
  } else {
    // 鼠标事件
    const pos = getEventPosition(event);
    // 竖屏：下部30%为摇杆区域（即 y > 70% 屏幕高度）
    const isInJoystickArea = pos.y > window.innerHeight * 0.7;

    if (isInJoystickArea) {
      startJoystick(pos);
    }
  }
}

function updateCameraSpeed(x: number) {
  // ===== 新的灵敏度计算逻辑 =====
  // 1. 以参考宽度对应弧度PI
  // 2. 使用指数函数计算灵敏度
  // 3. 离参考点越近，灵敏度越低；距离越远，灵敏度越高
  // 4. 时间间隔超过500ms时，重新计算参考点和参考宽度

  // 0. 检查时间间隔，超过500ms则重置参考点和参考宽度
  const currentTime = Date.now();
  const screenWidth = window.innerWidth;

  if (currentTime - lastCameraSpeedUpdateTime > 500) {
    touchStart.x = x;
    // 计算当前触摸点到左右边缘的距离（像素）
    const distanceToLeftPx = x;
    const distanceToRightPx = screenWidth - x;

    // 使用到最近边缘的距离作为新的参考宽度（像素）
    const referenceWidthPx = Math.min(distanceToLeftPx, distanceToRightPx);

    // 转换为英寸
    referenceWidthInches = pixelsToInches(referenceWidthPx, deviceDPI);
    referencePoint = x;

    // console.log('===== 时间间隔超过500ms，重置参考点 =====');
    // console.log('设备DPI:', deviceDPI);
    // console.log('新参考点X:', referencePoint.toFixed(2), 'px');
    // console.log('到左边缘距离:', distanceToLeftPx.toFixed(2), 'px');
    // console.log('到右边缘距离:', distanceToRightPx.toFixed(2), 'px');
    // console.log('新参考宽度:', referenceWidthPx.toFixed(2), 'px', '=', referenceWidthInches.toFixed(4), '英寸');
    // console.log('========================================');
  }
  lastCameraSpeedUpdateTime = currentTime;

  // 1. 获取当前触摸点位置（像素）
  const currentX = x;

  // 2. 计算当前触摸点到参考点的距离（像素）
  const distanceFromReferencePx = Math.abs(currentX - referencePoint);

  // 转换为英寸
  const distanceFromReferenceInches = pixelsToInches(distanceFromReferencePx, deviceDPI);

  // 3. 直接使用物理距离计算灵敏度，不进行归一化
  // 使用指数函数：sensitivity = baseSensitivity * e^(k * distance)
  // k 控制指数增长速度，distance 为实际物理距离（英寸）
  const k = 2; // 指数系数，降低以适应非归一化距离

  // 基础灵敏度（弧度/英寸）
  const baseSensitivityPerInch = 0.5; // 基础灵敏度
  let sensitivityPerInch = baseSensitivityPerInch * Math.exp(k * distanceFromReferenceInches);
  sensitivityPerInch = Math.min(sensitivityPerInch, 4);
  // sensitivityPerInch = sensitivityPerInch < sensitivityThreshold ? 0 : sensitivityPerInch;
  // 转换为弧度/像素
  const sensitivity = sensitivityPerInch / deviceDPI;

  // 4. 打印计算逻辑和结果
  // console.log('===== 摄像机旋转灵敏度计算（无归一化）=====');
  // console.log('设备DPI:', deviceDPI);
  // console.log(
  //   '屏幕宽度:',
  //   screenWidth.toFixed(2),
  //   'px',
  //   '=',
  //   pixelsToInches(screenWidth, deviceDPI).toFixed(4),
  //   '英寸',
  // );
  // console.log('参考点X:', referencePoint.toFixed(2), 'px');
  // console.log(
  //   '参考宽度:',
  //   referenceWidthInches.toFixed(4),
  //   '英寸',
  //   '=',
  //   inchesToPixels(referenceWidthInches, deviceDPI).toFixed(2),
  //   'px',
  // );
  // console.log('当前触摸点X:', currentX.toFixed(2), 'px');
  // console.log(
  //   '到参考点的距离:',
  //   distanceFromReferencePx.toFixed(2),
  //   'px',
  //   '=',
  //   distanceFromReferenceInches.toFixed(4),
  //   '英寸',
  // );
  // console.log('指数系数k:', k);
  // console.log('基础灵敏度:', baseSensitivityPerInch.toFixed(6), '弧度/英寸');
  // console.log('指数因子 e^(k*distance):', Math.exp(k * distanceFromReferenceInches).toFixed(4));
  // console.log('最终灵敏度:', sensitivityPerInch.toFixed(6), '弧度/英寸', '=', sensitivity.toFixed(6), '弧度/像素');
  // console.log('==========================================');
  // 5. 发送计算出的灵敏度
  emit('cameraRotationSpeed', sensitivity);
}

function startJoystick(pos: { x: number; y: number }) {
  isDragging = true;

  // 根据设备类型计算摇杆基座的半径
  const isMobile = window.innerWidth <= 768;
  const joystickBaseSize = isMobile ? 140 : 160; // 基座尺寸
  const joystickRadius = joystickBaseSize / 2; // 基座半径

  // 将摇杆移动到触摸位置（触摸点作为摇杆中心）
  joystickPosition.x = pos.x - joystickRadius;
  joystickPosition.y = window.innerHeight - pos.y - joystickRadius; // 转换为bottom坐标

  // 更新摇杆中心点
  joystickCenter = {
    x: pos.x,
    y: pos.y,
  };

  updateCameraSpeed(window.innerWidth / 4);
  // 记录初始触摸位置
  lastTouchPosition = { x: pos.x, y: pos.y };

  // 重置手柄位置
  moveHandle.x = 0;
  moveHandle.y = 0;
  emit('joystickMove', {
    x: 0,
    y: 0.1,
    angle: 0,
    distance: 0,
    edgeRatio: 0,
  });
  lastTJoystickY = 0.1;
  touchStart = pos;
}

function handleMove(event: MouseEvent | TouchEvent) {
  if (!isDragging) return;
  // Safari需要在touchmove中阻止默认行为
  if ('touches' in event) {
    event.preventDefault();
  }
  const pos = getEventPosition(event);
  // console.log('handleMove', pos.x, pos.y);
  // 只在 Safari 上使用 requestAnimationFrame 避免位置跳动
  if (isSafari()) {
    requestAnimationFrame(() => {
      updateJoystickPosition(pos.x, pos.y);
    });
  } else {
    updateJoystickPosition(pos.x, pos.y);
  }
}

function handleEnd() {
  if (!isDragging) return;

  isDragging = false;
  moveHandle.x = 0;
  moveHandle.y = 0;

  // 取消渐隐动画并立即隐藏弧线
  if (fadeOutAnimationId !== null) {
    cancelAnimationFrame(fadeOutAnimationId);
    fadeOutAnimationId = null;
    fadeOutStartTime = null;
  }
  edgeArc.show = false;
  edgeArc.opacity = 0.8; // 重置透明度

  // 摇杆回到默认位置
  joystickPosition.x = defaultPosition.x;
  joystickPosition.y = defaultPosition.y;

  emit('joystickMove', {
    x: 0,
    y: 0,
    angle: 0,
    distance: 0,
    edgeRatio: 0,
  });
}

function onGlobalMouseMove(event: MouseEvent) {
  handleMove(event);
}

function onGlobalMouseUp() {
  activeTouchId = null; // 重置触摸ID
  handleEnd();
}

function onGlobalTouchMove(event: TouchEvent) {
  handleMove(event);
}

function onGlobalTouchEnd(event: TouchEvent) {
  // 检查释放的触摸点中是否包含摇杆的触摸点
  if (activeTouchId !== null) {
    const changedTouches = Array.from(event.changedTouches);
    const joystickTouchReleased = changedTouches.some((touch) => touch.identifier === activeTouchId);

    if (joystickTouchReleased) {
      activeTouchId = null;
      handleEnd();
    }
  } else {
    // 如果没有激活的触摸ID（鼠标模式），直接结束
    handleEnd();
  }
}

/**
 * 开始弧线渐隐动画
 */
function startFadeOutAnimation() {
  // 取消之前的渐隐动画
  if (fadeOutAnimationId !== null) {
    cancelAnimationFrame(fadeOutAnimationId);
  }

  fadeOutStartTime = performance.now();

  const animate = (currentTime: number) => {
    if (fadeOutStartTime === null) return;

    const elapsed = currentTime - fadeOutStartTime;
    const progress = Math.min(elapsed / FADE_OUT_DURATION, 1); // 0 到 1

    // 从 0.8 渐变到 0
    edgeArc.opacity = 0.8 * (1 - progress);

    if (progress < 1) {
      // 继续动画
      fadeOutAnimationId = requestAnimationFrame(animate);
    } else {
      // 动画完成，隐藏弧线
      edgeArc.show = false;
      edgeArc.opacity = 0.8; // 重置透明度
      fadeOutAnimationId = null;
      fadeOutStartTime = null;
    }
  };

  fadeOutAnimationId = requestAnimationFrame(animate);
}

/**
 * 更新绿色弧线的显示
 * @param touchDeltaX 触摸增量X（正值=向右，负值=向左）
 */
function updateEdgeArc(touchDeltaX: number) {
  if (Math.abs(touchDeltaX) < 1) {
    return;
  }

  // 取消之前的渐隐动画
  if (fadeOutAnimationId !== null) {
    cancelAnimationFrame(fadeOutAnimationId);
    fadeOutAnimationId = null;
    fadeOutStartTime = null;
  }

  // 重置透明度并显示弧线
  edgeArc.opacity = 0.8;
  edgeArc.show = true;

  // 阈值：至少移动1像素
  // 使用与外圈容器相同的参数来绘制弧线
  const radius = 60; // 与外圈容器相同的半径

  if (touchDeltaX > 0) {
    // 向右移动：显示正右方向的弧线
    // 对齐外圈右方向弧线：M 145 50 A 60 60 0 0 1 145 110
    const x = 145;
    const startY = 50;
    const endY = 110;
    edgeArc.path = `M ${x} ${startY} A ${radius} ${radius} 0 0 1 ${x} ${endY}`;
  } else {
    // 向左移动：显示正左方向的弧线
    // 对齐外圈左方向弧线：M 15 110 A 60 60 0 0 1 15 50
    const x = 15;
    const startY = 110;
    const endY = 50;
    edgeArc.path = `M ${x} ${startY} A ${radius} ${radius} 0 0 1 ${x} ${endY}`;
  }

  // 开始渐隐动画
  startFadeOutAnimation();
}

function updateJoystickPosition(clientX: number, clientY: number) {
  const deltaX = clientX - joystickCenter.x;
  const deltaY = clientY - joystickCenter.y;

  let clampedDistance: number;

  if (props.isOrbitControlActive) {
    // OrbitControls 激活时：摇杆可以自由移动（八方向）
    const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);
    clampedDistance = Math.min(distance, maxDistance);

    // 计算限制后的位置
    if (distance > maxDistance) {
      const ratio = maxDistance / distance;
      moveHandle.x = deltaX * ratio;
      moveHandle.y = deltaY * ratio;
    } else {
      moveHandle.x = deltaX;
      moveHandle.y = deltaY;
    }
  } else {
    // OrbitControls 未激活时：只计算竖直方向的距离
    const verticalDistance = Math.abs(deltaY);
    clampedDistance = Math.min(verticalDistance, maxDistance);

    // 动态死区：根据摇杆中心（joystickCenter）的垂直位置调整死区大小
    // 摇杆中心越往上，死区越大
    const screenHeight = window.innerHeight;
    const joystickCenterYRatio = joystickCenter.y / screenHeight / 2; // 0 = 屏幕顶部, 1 = 屏幕底部

    // 死区范围：30% ~ 45%（相对于maxDistance）
    // 摇杆中心在顶部（joystickCenterYRatio = 0）：死区 = 45% of maxDistance
    // 摇杆中心在底部（joystickCenterYRatio = 1）：死区 = 30% of maxDistance
    const minDeadZoneRatio = 0.3; // 最小死区30%
    const maxDeadZoneRatio = 0.45; // 最大死区45%
    const deadZoneRatio = maxDeadZoneRatio - joystickCenterYRatio * (maxDeadZoneRatio - minDeadZoneRatio);
    const deadZone = joystickRadius * deadZoneRatio;

    // 摇杆球只在竖直方向移动（X轴固定为0）
    moveHandle.x = 0;
    // 保持原始方向（向上为负，向下为正）
    moveHandle.y = deltaY > 0 ? clampedDistance : -clampedDistance;

    // 如果在死区内，将距离设置为0（不触发移动，但摇杆球保持实际位置）
    if (verticalDistance <= deadZone) {
      clampedDistance = 0;
    }

    // 调试信息
    // console.log(
    //   '动态死区:',
    //   JSON.stringify({
    //     joystickCenterY: joystickCenter.y.toFixed(0),
    //     joystickCenterYRatio: joystickCenterYRatio.toFixed(2),
    //     deadZoneRatio: (deadZoneRatio * 100).toFixed(1) + '%',
    //     deadZone: deadZone.toFixed(1),
    //     // maxDistance: maxDistance.toFixed(1),
    //     verticalDistance: verticalDistance.toFixed(1),
    //     isInDeadZone: verticalDistance <= deadZone,
    //   }),
    // );
  }

  // 计算角度
  const angle = Math.atan2(deltaY, deltaX);

  // 计算触摸增量并更新绿色弧线
  const touchDeltaX = clientX - lastTouchPosition.x;
  updateEdgeArc(touchDeltaX);

  // 发送标准化的摇杆数据 (-1 到 1)
  const normalizedX = moveHandle.x / maxDistance;
  let normalizedY = -moveHandle.y / maxDistance; // Y轴反转，向上为负

  // 如果在死区内，将 normalizedY 设置为 0（不触发角色移动）
  if (clampedDistance === 0) {
    normalizedY = 0;
  }

  // console.log('摇杆数据:', {
  //   normalizedX,
  //   normalizedY,
  //   moveHandleY: moveHandle.y,
  //   deltaY,
  //   clampedDistance
  // });

  // 计算触摸增量Y（touchDeltaX 已在上面计算过）
  const touchDeltaY = clientY - lastTouchPosition.y;

  // 根据移动方向调整touchDeltaX的符号
  let finalTouchDeltaX = touchDeltaX;
  if (normalizedY < 0 && clampedDistance !== 0) {
    finalTouchDeltaX = -touchDeltaX;
  }
  // 更新上一次位置
  lastTouchPosition = { x: clientX, y: clientY };
  updateCameraSpeed(lastTouchPosition.x);
  // 发送触摸增量
  emit('touchDelta', { x: finalTouchDeltaX, y: touchDeltaY });
  if (normalizedY === 0) {
    normalizedY = lastTJoystickY;
  }

  lastTJoystickY = normalizedY;
  emit('joystickMove', {
    x: normalizedX,
    y: normalizedY,
    angle: angle,
    distance: clampedDistance / maxDistance,
  });
}

/**
 * 从外部显示绿色弧线（用于键盘控制）
 * @param direction 'left' 或 'right'
 * @param startFadeOut 是否立即开始渐隐动画（默认true）
 */
function showEdgeArcFromKeyboard(direction: 'left' | 'right', startFadeOut: boolean = true) {
  // 取消之前的渐隐动画
  if (fadeOutAnimationId !== null) {
    cancelAnimationFrame(fadeOutAnimationId);
    fadeOutAnimationId = null;
    fadeOutStartTime = null;
  }

  // 重置透明度并显示弧线
  edgeArc.opacity = 0.8;
  edgeArc.show = true;

  // 使用与外圈容器相同的参数来绘制弧线
  const radius = 60; // 与外圈容器相同的半径

  if (direction === 'right') {
    // 右侧弧线：M 145 50 A 60 60 0 0 1 145 110
    const x = 145;
    const startY = 50;
    const endY = 110;
    edgeArc.path = `M ${x} ${startY} A ${radius} ${radius} 0 0 1 ${x} ${endY}`;
  } else {
    // 左侧弧线：M 15 110 A 60 60 0 0 1 15 50
    const x = 15;
    const startY = 110;
    const endY = 50;
    edgeArc.path = `M ${x} ${startY} A ${radius} ${radius} 0 0 1 ${x} ${endY}`;
  }

  // 根据参数决定是否开始渐隐动画
  if (startFadeOut) {
    startFadeOutAnimation();
  }
}

/**
 * 开始弧线渐隐动画（用于键盘松开时调用）
 */
function startEdgeArcFadeOut() {
  if (edgeArc.show) {
    startFadeOutAnimation();
  }
}

/**
 * 强制重置摇杆状态（用于页面失去焦点时）
 */
function forceReset() {
  // 如果正在拖动，强制结束
  if (isDragging) {
    handleEnd();
  }

  // 重置所有状态
  isDragging = false;
  activeTouchId = null;
  moveHandle.x = 0;
  moveHandle.y = 0;

  // 隐藏弧线
  if (fadeOutAnimationId !== null) {
    cancelAnimationFrame(fadeOutAnimationId);
    fadeOutAnimationId = null;
    fadeOutStartTime = null;
  }
  edgeArc.show = false;
  edgeArc.opacity = 0.8;

  // 摇杆回到默认位置
  joystickPosition.x = defaultPosition.x;
  joystickPosition.y = defaultPosition.y;

  // 发送停止信号
  emit('joystickMove', {
    x: 0,
    y: 0,
    angle: 0,
    distance: 0,
    edgeRatio: 0,
  });
}

// 暴露方法给父组件
// 操作模式相关方法
function getOperationModeText(): string {
  switch (currentOperationMode.value) {
    case OperationMode.AUTO:
      return props.isOrbitControlActive ? '双手操作模式' : '单手操作模式';
    case OperationMode.SINGLE:
      return '单手操作模式';
    case OperationMode.DUAL:
      return '双手操作模式';
    default:
      return '单手操作模式';
  }
}

function getOperationModeDescription(): string {
  switch (currentOperationMode.value) {
    case OperationMode.AUTO:
      return props.isOrbitControlActive
        ? isPCDevice.value
          ? 'WASD控制方向，鼠标控制摄像头'
          : '左侧摇杆控制方向，滑动屏幕右侧控制摄像头'
        : isPCDevice.value
          ? 'WS控制前后，AD控制摄像头'
          : '摇杆前后控制方向，左右控制摄像头';
    case OperationMode.SINGLE:
      return isPCDevice.value ? 'WS控制前后，AD控制摄像头' : '摇杆前后控制方向，左右控制摄像头';
    case OperationMode.DUAL:
      return isPCDevice.value ? 'WASD控制方向，鼠标控制摄像头' : '左侧摇杆控制方向，滑动屏幕右侧控制摄像头';
    default:
      return '摇杆前后控制方向，左右控制摄像头';
  }
}

function getThumbPosition(): number {
  // 根据设备类型调整选项宽度
  const optionWidth = window.innerWidth <= 768 ? 35 : 40;
  switch (currentOperationMode.value) {
    case OperationMode.AUTO:
      return 0;
    case OperationMode.SINGLE:
      return optionWidth;
    case OperationMode.DUAL:
      return optionWidth * 2;
    default:
      return 0;
  }
}

function setOperationMode(mode: OperationMode) {
  currentOperationMode.value = mode;
  emit('operationModeChange', mode);
  console.log(`操作模式切换为: ${mode}`);
}

defineExpose({
  showEdgeArcFromKeyboard,
  startEdgeArcFadeOut,
  forceReset,
});
</script>

